)
@delete_version.mapping.patch
def update_version_label(self, request, pk=None, version_id=None):
    serializer = DocumentVersionLabelSerializer(data=request.data)
    serializer.is_valid(raise_exception=True)

    root_doc = self._get_root_doc_for_version_action(pk)
    if request.user is not None and not has_perms_owner_aware(
        request.user,
        "change_document",
        root_doc,
    ):
        return HttpResponseForbidden("Insufficient permissions")

version_doc = self._get_version_doc_for_root(root_doc, version_id)
old_label = version_doc.version_label
version_doc.version_label = serializer.validated_data["version_label"]
version_doc.save(update_fields=["version_label"])
root_doc.modified = timezone.now()
Document.objects.filter(pk=root_doc.pk).update(modified=root_doc.modified)

if settings.AUDIT_LOG_ENABLED and old_label != version_doc.version_label:
    actor = (
        request.user if request.user and request.user.is_authenticated else None
    )
    LogEntry.objects.log_create(
        instance=root_doc,
        changes={
            "Version Label": [old_label, version_doc.version_label],
        },
        action=LogEntry.Action.UPDATE,
        actor=actor,
        additional_data={
            "reason": "Version label updated",
            "version_id": version_doc.id,
        },
    )

document_updated.send(
    sender=self.__class__,
    document=root_doc,
)

return Response(
    {
        "id": version_doc.id,
        "added": version_doc.added,
        "version_label": version_doc.version_label,
        "checksum": version_doc.checksum,
        "is_root": version_doc.id == root_doc.id,
    },
)

def validate(self, attrs):
    if (
        "archive_serial_number" in attrs
        and attrs["archive_serial_number"] is not None
        and len(str(attrs["archive_serial_number"])) > 0
        and Document.deleted_objects.filter(
            archive_serial_number=attrs["archive_serial_number"],
        ).exists()
    ):
        raise serializers.ValidationError(
            {
                "archive_serial_number": [
                    "Document with this Archive Serial Number already exists in the trash.",
                ],
            },
        )
    return super().validate(attrs)

def to_internal_value(self, data):
    if (
        "created" in data
        and isinstance(data["created"], str)
        and ":" in data["created"]
    ):
        # Handle old format of isoformat datetime string
        parsed = parse_datetime(data["created"])
        if parsed:
            if is_naive(parsed):
                parsed = make_aware(parsed, get_current_timezone())
            data["created"] = parsed.astimezone().date()
    return super().to_internal_value(data)

def get_serializer(self, *args, **kwargs):
    serializer_class = self.get_serializer_class()
    if isinstance(serializer_class, type) and issubclass(
        serializer_class,
        SerializerWithPerms,
    ):
        kwargs.setdefault("user", self.request.user)
        try:
            full_perms = get_boolean(
                str(self.request.query_params.get("full_perms", "false")),
            )
        except ValueError:
            full_perms = False
        kwargs.setdefault(
            "full_perms",
            full_perms,
        )
    return super().get_serializer(*args, **kwargs)

def _queryset(self, view):
    assert hasattr(view, 'get_queryset') \
        or getattr(view, 'queryset', None) is not None, (
        'Cannot apply {} on a view that does not set '
        '`.queryset` or have a `.get_queryset()` method.'
    ).format(self.__class__.__name__)

    if hasattr(view, 'get_queryset'):
        queryset = view.get_queryset()
        assert queryset is not None, (
            f'{view.__class__.__name__}.get_queryset() returned None'
        )
        return queryset
    return view.queryset

def get_boolean(boolstr: str) -> bool:
    """
    Return a boolean value from a string representation.
    """
    return bool(boolstr.lower() in ("yes", "y", "1", "t", "true"))

def get_serializer_context(self):
    """
    Get all permissions of the current list of objects at once and pass them to the serializer.
    This avoid fetching permissions object by object in database.
    """
    context = super().get_serializer_context()

    if getattr(self, "action", None) != "list":
        # Batching only pays off across a page of objects; for single-object
        # actions (retrieve, update, ...) the per-object fallback in
        # get_user_can_change()/_get_perms() is cheap and avoids scanning
        # the whole queryset here.
        return context

    # Check which objects are being paginated
    page = getattr(self, "paginator", None)
    if page and hasattr(page, "page"):
        queryset = page.page.object_list
    elif hasattr(self, "page"):
        queryset = self.page
    else:
        queryset = self.filter_queryset(self.get_queryset())

    model_name = self.queryset.model.__name__.lower()
    permission_name_view = f"view_{model_name}"
    permission_name_change = f"change_{model_name}"

    user_perms = self._get_object_perms(
        objects=queryset,
        perm_codenames=[permission_name_view, permission_name_change],
        actor="users",
    )
    group_perms = self._get_object_perms(
        objects=queryset,
        perm_codenames=[permission_name_view, permission_name_change],
        actor="groups",
    )

    context["users_view_perms"] = {
        pk: user_perms[pk][permission_name_view] for pk in user_perms
    }
    context["users_change_perms"] = {
        pk: user_perms[pk][permission_name_change] for pk in user_perms
    }
    context["groups_view_perms"] = {
        pk: group_perms[pk][permission_name_view] for pk in group_perms
    }
    context["groups_change_perms"] = {
        pk: group_perms[pk][permission_name_change] for pk in group_perms
    }

    return context

def annotate_effective_content(documents: QuerySet[Document]) -> QuerySet[Document]:
    """
    Annotates documents with the content of their newest version unless the
    queryset already carries the annotation, falling back to their own, so
    get_effective_content() can answer from the row rather than querying for
    the versions of each document.
    """
    if "effective_content" in documents.query.annotations:
        return documents
    return documents.annotate(
        effective_content=Coalesce(
            Subquery(
                versions_newest_first(
                    Document.objects.filter(root_document=OuterRef("pk")),
                ).values("content")[:1],
            ),
            F("content"),
        ),
    )

def versions_newest_first(documents: QuerySet[Document]) -> QuerySet[Document]:
    """
    Sorts versions so the newest one comes first using version_index and not on id,
    because an existing document can be merged in as a version
    """
    return documents.order_by(F("version_index").desc(nulls_last=True), "-id")

def create(self, validated_data):
    # default to current user if not set
    request = self.context.get("request")
    if (
        "owner" not in validated_data
        or (request is not None and "owner" not in request.data)
    ) and self.user:
        validated_data["owner"] = self.user
    permissions = None
    if "set_permissions" in validated_data:
        permissions = validated_data.pop("set_permissions")
    self.validate_unique_together(validated_data)
    instance = super().create(validated_data)
    if permissions is not None:
        self._set_permissions(permissions, instance)
    return instance
